package com.clouddocs.document.application;
import com.clouddocs.audit.application.*; import com.clouddocs.audit.domain.AuditAction; import com.clouddocs.document.domain.Folder; import com.clouddocs.document.infrastructure.JdbcFolderRepository; import com.clouddocs.identity.domain.User; import com.clouddocs.operations.api.InvalidRequestException; import com.clouddocs.tenancy.application.TenantAuthorizationService; import org.springframework.stereotype.Service; import java.util.*;
@Service public class FolderService { private final JdbcFolderRepository repo; private final TenantAuthorizationService auth; private final AuditService audit; public FolderService(JdbcFolderRepository r,TenantAuthorizationService a,AuditService s){repo=r;auth=a;audit=s;}
 public Folder require(UUID tenant,UUID id){return repo.find(id,tenant);}
 public Folder create(User u,UUID tenant,String name,UUID parent){auth.requireWriteAccess(u,tenant);if(parent!=null)require(tenant,parent);Folder f=repo.insert(tenant,name.trim(),parent);audit.record(tenant,u.id(),AuditAction.FOLDER_CREATED,"FOLDER",f.id());return f;}
 public List<Folder> list(User u,UUID tenant,UUID parent){auth.requireMembership(u,tenant);if(parent!=null)require(tenant,parent);return repo.list(tenant,parent);}
 public Folder update(User u,UUID tenant,UUID id,String name,UUID parent){auth.requireWriteAccess(u,tenant);require(tenant,id);if(parent!=null){require(tenant,parent);if(parent.equals(id))throw new InvalidRequestException("A folder cannot be its own parent");UUID cursor=parent;while(cursor!=null){Folder p=require(tenant,cursor);if(p.id().equals(id))throw new InvalidRequestException("Folder move would create a cycle");cursor=p.parentId();}}repo.update(id,tenant,name.trim(),parent);Folder f=require(tenant,id);audit.record(tenant,u.id(),AuditAction.FOLDER_UPDATED,"FOLDER",id);return f;}
}
